    $('#instead-checkpoint').onclick=()=>{const d=draft();if(!d.rock)return toast('Choose a Rock first, then review its checkpoint.');editItem(null,'checkpoint',{world:d.world,project:d.project,rock:d.rock,title:d.title,description:d.description,due_at:d.due_at||date(14)})};
