  $('#review-snooze').onclick=async()=>{i.review_snooze_until=new Date(Date.now()+3*DAY).toISOString();log('Snoozed critical review for 3 days',i.id);if(await save()){$('#modal').close();render()}};
  $('#review-dismiss').onclick=async()=>{log('Dismissed critical review',i.id);if(await save()){$('#modal').close();render()}};
