  f.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));if(!d.world)return toast('Choose a World, or save this capture for later review.');const c=await retain(true);if(!await save())return;editItem(null,d.type,{world:d.world,project:d.type==='rock'?'':d.project,title:d.text.split('\n')[0].slice(0,180),description:d.type==='note'?d.text:'',capture_id:c.id});};
