async function uploadFile(file){
  if(file.size>20*1048576)throw Error('Maximum file size is 20 MB.');
  const upload=await api('upload/start','POST',{name:file.name,size:file.size});
  for(let offset=0,index=0;offset<file.size;offset+=upload.chunkSize,index++){
    const part=file.slice(offset,offset+upload.chunkSize),data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result.split(',')[1]);r.onerror=()=>rej(Error('Could not read file.'));r.readAsDataURL(part)});
    await api('upload/chunk','POST',{id:upload.id,index,data});
  }
  return api('upload','POST',{id:upload.id});
}
function openUpload(file){if(!file)return;editItem(null,'resource',{title:file.name,stagedFile:file})}
function reviewExtracted(i){const candidates=(i.extracted_text||'').split(/\n|(?<=[.!?])\s+/).filter(line=>/\b(todo|to-do|action|follow up|deadline|due|will |must |need to|decid)\b/i.test(line)).slice(0,15);modal(`<p class="eyebrow">REVIEW EXTRACTED LANGUAGE</p><h2>Possible next moves</h2><p class="muted">These are keyword matches, not confirmed commitments. Choose a line, then confirm its World, Project, dates and reminder.</p>${candidates.map((text,n)=>`<button class="proposal-line" data-candidate="${n}">${esc(text.slice(0,500))}</button>`).join('')||'<p class="empty">No action-like lines found. You can still create a To-Do from your own interpretation.</p>'}`);$$('[data-candidate]').forEach(b=>b.onclick=()=>editItem(null,'todo',{title:candidates[Number(b.dataset.candidate)].slice(0,180),description:'Source: '+i.title,world:i.world,project:i.project||'',source_resource:i.id}))}
function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
const music=new FocusMusic();let resumeAfterRecording=false;
function updateMusicControl(){const button=$('#music-control');if(!button)return;button.classList.toggle('is-playing',!music.paused);let level=button.querySelector('.music-volume-chip');if(!level){level=document.createElement('span');level.className='music-volume-chip';level.setAttribute('aria-hidden','true');button.append(level)}level.textContent=Math.round(music.volume*100)+'%';button.title=music.paused?'Focus music':'Focus music · '+Math.round(music.volume*100)+'%'}
music.onChange(updateMusicControl);
function pauseMusic(){resumeAfterRecording=!music.paused;music.pause(true)}
function resumeMusic(){if(resumeAfterRecording){music.play().catch(()=>{});resumeAfterRecording=false}}
function musicModal(){
  modal(`<p class="eyebrow">A LITTLE SPACE TO FOCUS</p><h2>Focus music</h2><p class="muted">An unhurried soundtrack. Every track loops with a gentle fade.</p><label>Track<select id="music-track"><option value="">Off / silence</option>${(config.tracks||[]).map(t=>`<option value="${esc(t.url)}" ${(music.track||state.preferences.music.track)===t.url?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><div class="music-level-row"><label for="music-volume">Volume</label><output id="music-percent">${Math.round(music.volume*100)}%</output></div><input id="music-volume" type="range" min="0" max="1" step="0.01" value="${music.volume}" aria-label="Music volume"><div class="music-meter" aria-hidden="true">${Array.from({length:24},()=>'<i></i>').join('')}</div><p id="music-status" class="muted micro" role="status">${music.paused?'Ready when you are.':'Playing · Loop on'}</p><label class="check-label"><input id="music-remember" type="checkbox" ${state.preferences.music.remember?'checked':''}>Remember my selected track</label><button id="music-play" class="primary full">${music.paused?'Play selected track':'Pause'}</button><p class="muted micro">Music pauses during voice capture. Playback starts only when you press Play.</p>`);
  const volume=$('#music-volume'),play=$('#music-play'),select=$('#music-track'),status=$('#music-status');
  volume.oninput=e=>{music.setVolume(e.target.value);$('#music-percent').textContent=Math.round(music.volume*100)+'%'};
  play.onclick=async()=>{play.disabled=true;try{if(!music.paused){await music.pause();status.textContent='Paused.'}else if(select.value){await music.play(select.value);state.preferences.music={track:$('#music-remember').checked?select.value:'',remember:$('#music-remember').checked};await save();status.textContent='Playing · Loop on'}else status.textContent='Choose a track to begin.'}catch{status.textContent='The selected track could not play. Try again.'}finally{play.disabled=false;play.textContent=music.paused?'Play selected track':'Pause'}};
  const remember=async()=>{state.preferences.music={track:$('#music-remember').checked?select.value:'',remember:$('#music-remember').checked};await save()};$('#music-remember').onchange=remember;
  select.onchange=async()=>{await remember();if(music.paused)return;try{if(select.value){await music.play(select.value);status.textContent='Playing · Loop on'}else{await music.pause();status.textContent='Music is off.'}play.textContent=music.paused?'Play selected track':'Pause'}catch{status.textContent='This track could not play.'}};
  const bars=[...document.querySelectorAll('.music-meter i')];let previous=0;function meter(t){if(!play.isConnected||!$('#modal').open)return;if(t-previous>70){const level=music.level();bars.forEach((b,i)=>b.classList.toggle('lit',i<Math.round(level*24)));previous=t;}requestAnimationFrame(meter)}requestAnimationFrame(meter);
}

function notificationItems(){const p=state.preferences.notifications,now=new Date(),at=localInput(now).slice(11),quiet=p.quietStart<p.quietEnd?(at>=p.quietStart&&at<p.quietEnd):(at>=p.quietStart||at<p.quietEnd),list=[];
  for(const i of state.items.filter(i=>isVisible(state,i)&&!complete(i))){if(i.reminder_at&&new Date(i.reminder_at)<=now)list.push({id:'reminder-'+i.id+'-'+i.reminder_at,item:i.id,title:i.title,reason:'Requested reminder · '+fmtTime(i.reminder_at)});if(!p.enabled||i.linked_checkpoint)continue;const d=itemDate(i),a=attention(i);if(p.categories.includes('overdue')&&a.overdue)list.push({id:'overdue-'+i.id+'-'+today(),item:i.id,title:i.title,reason:'Overdue since '+fmt(d)});else if(p.categories.includes('due')&&d===today())list.push({id:'due-'+i.id+'-'+today(),item:i.id,title:i.title,reason:'Due today'});else if(p.categories.includes('approaching')&&d>today()&&d<=date(Number(p.leadDays)))list.push({id:'soon-'+i.id+'-'+today(),item:i.id,title:i.title,reason:'Approaching deadline · '+fmt(d)});if(p.categories.includes('offtrack')&&i.type==='rock'&&i.status==='off'&&rockState(state,i)==='Active')list.push({id:'offtrack-'+i.id+'-'+today(),item:i.id,title:i.title,reason:'Off-track Active Rock'});}
  if(p.enabled&&p.categories.includes('digest')){const open=state.items.filter(i=>isVisible(state,i)&&!complete(i));list.push({id:'digest-'+today(),route:'output',title:p.frequency==='weekly'?'Weekly digest':'Daily digest',reason:`${open.filter(i=>i.type==='todo').length} unfinished To-Dos · ${open.filter(i=>!i.linked_checkpoint&&attention(i).overdue).length} overdue obligations · ${open.filter(i=>i.type==='issue').length} open Issues`});}
  return {list,quiet};
}
function notificationsModal(){const {list,quiet}=notificationItems();modal(`<h2>Notifications</h2><p class="muted">${quiet?'Quiet hours are active. ':''}Due dates and reminder times are separate. Browser alerts require this app to be open.</p>${list.map(n=>`<button class="notification-line" ${n.route?'data-nav="'+n.route+'"':'data-edit="'+n.item+'"'}><strong>${esc(n.title)}</strong><small>${esc(n.reason)}</small></button>`).join('')||'<p class="empty">You’re all caught up.</p>'}<button class="text-button" data-nav="settings">Notification settings</button>`)}
function checkNotifications(){if(!state||!('Notification' in window)||Notification.permission!=='granted')return;const {list,quiet}=notificationItems();if(quiet)return;const p=state.preferences.notifications,at=localInput(new Date()).slice(11),digestReady=at>=p.digestTime&&(p.frequency!=='weekly'||new Date().getDay()===Number(p.weekDay));const due=list.filter(n=>n.id.startsWith('reminder-'));if(digestReady&&p.enabled)due.push(...list.filter(n=>!n.id.startsWith('reminder-')));const pending=due.filter(n=>!notificationSeen.has(n.id)&&!localStorage.getItem('cnfdnt-alert-'+n.id));if(!pending.length)return;pending.forEach(n=>{notificationSeen.add(n.id);localStorage.setItem('cnfdnt-alert-'+n.id,'shown')});if(pending.length)new Notification(pending.length===1?pending[0].title:`CNFDNT · ${pending.length} items need attention`,{body:pending.map(n=>n.reason+': '+n.title).slice(0,3).join('\n'),tag:'cnfdnt-alerts'});}
async function googleManage(){try{const list=await api('google/calendars');modal(`<h2>Choose calendars</h2><p class="muted">Import read-only. Choose a World for each selected calendar. Deselecting a calendar removes its imported copies, not the originals.</p><form id="google-form">${list.map((c,n)=>{const selected=config.google.selected.find(s=>s.id===c.id);return `<div class="calendar-choice"><label class="check-label"><input type="checkbox" name="calendar" value="${n}" ${selected?'checked':''}>${esc(c.name)}</label><label>Destination World<select name="world-${n}">${worldOptions(selected?.world)}</select></label></div>`}).join('')}<button class="primary full">Import / synchronize selected calendars</button></form>`);$('#google-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const f=new FormData(e.target),selected=f.getAll('calendar').map(n=>({id:list[Number(n)].id,world:f.get('world-'+n)}));await api('google/sync','POST',{selected});state=await api('state');config=await api('config');$('#modal').close();render();toast('Read-only calendars synchronized.')}catch(e){toast(e.message)}finally{b.disabled=false}}}catch(e){toast(e.message)}}
