  $$('[data-track]').forEach(b=>b.onclick=async()=>{const w=state.worlds.find(x=>x.id===b.dataset.track);if(!w)return;w.status_override=b.dataset.value||null;log('Set World status',w.id,w.status_override||'auto');if(await save())render()});
