  if($('#more-nav'))$('#more-nav').onclick=()=>modal(`<h2>Your workspace</h2><nav class="mobile-menu">${[...navItems,'settings'].map(n=>`<button data-nav="${n}"><span>${icons[n]}</span>${names[n]}</button>`).join('')}</nav>`);
