  if($('#timeline-span'))$('#timeline-span').onchange=e=>{timelineSpan=Number(e.target.value);render()};
  const period=dir=>{if(calendarMode==='month'){const d=new Date(calendarDate+'T12:00:00');calendarDate=localDate(new Date(d.getFullYear(),d.getMonth()+dir,1,12))}else calendarDate=datePlus(calendarDate,dir*(calendarMode==='week'?7:calendarMode==='list'?timelineSpan:1));render()};
  if($('#calendar-prev')){$('#calendar-prev').onclick=()=>period(-1);$('#calendar-next').onclick=()=>period(1);$('#calendar-today').onclick=()=>{calendarDate=today();render()};}
