  if($('#archive-search'))$('#archive-search').oninput=e=>{search=e.target.value;const q=search.toLowerCase();$('#archive-results').innerHTML=archiveRows(state.items.filter(i=>(i.archived_at||state.worlds.find(w=>w.id===i.world)?.archived_at||state.projects.find(p=>p.id===i.project)?.archived_at)&&(i.title+' '+(i.description||'')).toLowerCase().includes(q)))};
  if($('#output-form')){
    const f=$('#output-form');bindAssociations(f);f.onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;b.textContent='Preparing your draft…';try{const d=Object.fromEntries(new FormData(f));outputDraft={...await api('output','POST',d),prompt:d.prompt,world:d.world,project:d.project,created_at:stamp()};render()}catch(e){toast(e.message)}finally{b.disabled=false;b.textContent='Generate draft ↗'}};
  }
