document.addEventListener('click',async e=>{
  let b=e.target.closest('button');if(!b&&!e.target.closest('a,input,textarea,select,summary')){const card=e.target.closest('[data-card-world],[data-card-rock],[data-card-project],[data-card-edit]');if(card){if(card.dataset.cardWorld)return navigate('worlds',card.dataset.cardWorld);b=card.querySelector('[data-rock],[data-project],[data-edit]');}}if(!b)return;
  try{
    if(b.hasAttribute('data-intake'))return intake();
    if(b.hasAttribute('data-rock')){$('#modal').close();rockId=b.dataset.rock;world=null;project=null;view='rocks';render();window.scrollTo(0,0);animatePage();return}
    if(b.hasAttribute('data-link-rock'))return linkRock(b.dataset.linkRock);
    if(b.hasAttribute('data-rock-todo')){const r=state.items.find(i=>i.id===b.dataset.rockTodo);return editItem(null,'todo',{world:r.world,rock:r.id})}
    if(b.hasAttribute('data-priority')){reorder(state,b.dataset.priority,Number(b.dataset.direction),b.dataset.scope);if(await save())render();return;}
    if(b.hasAttribute('data-mvp-move')){const n=state.focusThree.indexOf(b.dataset.mvpMove),to=n+Number(b.dataset.direction);if(to>=0&&to<state.focusThree.length){[state.focusThree[n],state.focusThree[to]]=[state.focusThree[to],state.focusThree[n]];if(await save())render()}return;}
    if(b.hasAttribute('data-nav')){$('#modal').close();return navigate(b.dataset.nav)}
    if(b.hasAttribute('data-world')){$('#modal').close();return navigate('worlds',b.dataset.world)}
    if(b.hasAttribute('data-project')){$('#modal').close();const p=state.projects.find(p=>p.id===b.dataset.project);return navigate('projects',p.world,p.id)}
    if(b.hasAttribute('data-tab')){tab=b.dataset.tab;filter='open';search='';render();animatePage();return}
    if(b.hasAttribute('data-edit'))return editItem(b.dataset.edit);
    if(b.hasAttribute('data-add'))return editItem(null,b.dataset.add);
    if(b.hasAttribute('data-new-world'))return editWorld();
    if(b.hasAttribute('data-edit-world'))return editWorld(b.dataset.editWorld);
    if(b.hasAttribute('data-new-project'))return editProject();
    if(b.hasAttribute('data-edit-project'))return editProject(b.dataset.editProject);
    if(b.hasAttribute('data-delete'))return deleteItem(b.dataset.delete);
    if(b.hasAttribute('data-complete'))return toggleComplete(b.dataset.complete);
    if(b.hasAttribute('data-capture'))return captureModal();
    if(b.hasAttribute('data-review-capture')){const c=state.captures.find(c=>c.id===b.dataset.reviewCapture);return captureModal(c.text,c.id)}
    if(b.hasAttribute('data-review'))return reviewAged(state.items.find(i=>i.id===b.dataset.review));
    if(b.hasAttribute('data-propose-checkpoint')){const c=state.items.find(i=>i.id===b.dataset.proposeCheckpoint);if(scheduledCheckpoint(c))return toast('Review this checkpoint when it enters the 14-day window.');return editItem(null,'todo',{world:c.world,rock:c.rock,project:c.project,title:c.title,description:c.description,due_at:c.due_at<today()?today():c.due_at,linked_checkpoint:c.id})}
    if(b.hasAttribute('data-new-checkpoint'))return newCheckpoint(b.dataset.newCheckpoint);
    if(b.hasAttribute('data-solve'))return solveIssue(b.dataset.solve);
    if(b.hasAttribute('data-filter')){filter=b.dataset.filter;return render()}
    if(b.hasAttribute('data-calendar')){calendarMode=b.dataset.calendar;return render()}
    if(b.hasAttribute('data-day')){calendarDate=b.dataset.day;calendarMode='day';return render()}
    if(b.hasAttribute('data-output')){outputDraft=structuredClone(state.outputs.find(o=>o.id===b.dataset.output));return render()}
    if(b.hasAttribute('data-rock-info'))return modal('<h2>Choose outcomes that matter.</h2><p>A Rock is a substantial outcome for roughly one quarter. Choose an observable definition of done so you can tell when you have finished. Optional Projects organize the steps that deliver it.</p><p>Example: “Welcome 100 founding members by December 20.” Done means 100 paid members have completed onboarding. A launch Project and weekly outreach checkpoints can support it.</p><p>Review on/off-track status regularly: is the outcome still achievable by its date? Each World has up to three active Rocks so its priorities stay clear. Extra Rocks wait in that World’s queue. Across every World, star up to three Most Valuable Priorities for special attention. These stars do not change any World’s active queue.</p>');
    if(b.hasAttribute('data-move')){const i=state.items.find(i=>i.id===b.dataset.move);const scope=i.type==='rock'?'world:'+i.world:scopeKey(world,project);reorder(state,i.id,Number(b.dataset.direction),scope);log('Reordered in '+scope,i.id);if(await save()){$('#modal').close();render()}return;}
    if(b.hasAttribute('data-focus')){const id=b.dataset.focus;if(state.focusThree.includes(id))state.focusThree=state.focusThree.filter(x=>x!==id);else{if(rockState(state,state.items.find(i=>i.id===id))!=='Active')return toast('Activate this Rock in its World before starring.');if(state.focusThree.length>=3)return toast('All three MVP slots are full. Remove one first.');state.focusThree.push(id)}if(await save())render();return;}
    if(b.hasAttribute('data-deactivate')){const i=state.items.find(i=>i.id===b.dataset.deactivate);i.deactivated=!i.deactivated;log(i.deactivated?'Deactivated Rock':'Reactivated Rock',i.id);if(await save())render();return;}
    if(b.hasAttribute('data-restore')){const i=state.items.find(i=>i.id===b.dataset.restore);delete i.archived_at;delete i.completed_at;log('Restored and reopened item',i.id);if(await save())render();return;}
    if(b.hasAttribute('data-restore-parent')){const p=[...state.worlds,...state.projects].find(x=>x.id===b.dataset.restoreParent);if(!p.world&&state.worlds.filter(w=>!w.archived_at).length>=10)return toast('Archive an active World before restoring another.');delete p.archived_at;log('Restored '+(p.world?'Project':'World'),p.id);if(await save())render();return;}
  }catch(err){toast(err.message)}
});
document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='c'&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)&&!$('#modal').open&&state&&!e.ctrlKey&&!e.metaKey){e.preventDefault();captureModal()}});
setInterval(checkNotifications,30000);
setInterval(async()=>{if(!state||saveError||$('#modal').open||$('.intake')||['settings','capture','output'].includes(view)||/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName))return;try{const latest=await api('state');if(latest.revision!==state.revision){state=latest;render();}}catch{}},60000);
try{state=await api('state');config=await api('config');if(new URLSearchParams(location.search).has('google'))navigate('settings');else intake()}catch{login()}

function guide(){return heading('Your CNFDNT OS guide','A place for the thought, the outcome, and the next move.')+`<section class="guide"><div class="guide-index"><button class="subtle-button" id="guide-expand">Expand all sections</button><button class="text-button" data-nav="settings">Settings & backup</button></div>${guideSections.map(([title,text],n)=>`<details class="panel" ${n===0?'open':''}><summary>${esc(title)}</summary><p>${esc(text)}</p></details>`).join('')}</section>`}

function rockHorizon(r){const milestones=state.items.filter(i=>i.rock===r.id&&i.due_at&&!i.linked_checkpoint&&isVisible(state,i)).sort((a,b)=>a.due_at.localeCompare(b.due_at));const start=r.created_at.slice(0,10),end=[r.due_at,today(),...milestones.map(i=>i.due_at)].sort().at(-1),span=Math.max(1,Date.parse(end)-Date.parse(start)),position=d=>Math.max(0,Math.min(100,(Date.parse(d.slice(0,10))-Date.parse(start))/span*100));const elapsed=Math.round(position(today()));return `<section class="panel rock-horizon"><div class="section-heading"><h3>Rock timeline</h3><span class="muted micro">${elapsed}% of the displayed time window elapsed</span></div><div class="rock-time-axis"><div class="rock-time-progress" style="width:${elapsed}%"></div><div class="rock-today" style="left:${elapsed}%"><span>Today</span><i></i></div>${milestones.map(i=>`<button class="rock-milestone ${complete(i)?'finished':''}" style="left:${position(i.due_at)}%" data-edit="${i.id}" aria-label="${esc(i.title)} · ${fmt(i.due_at)}" title="${esc(i.title)} · ${fmt(i.due_at)}"></button>`).join('')}<span class="rock-deadline" style="left:${position(r.due_at)}%" title="Rock due ${fmt(r.due_at)}">◇</span></div><div class="rock-time-labels"><span>Started ${fmt(start)}</span><strong>Rock due ${fmt(r.due_at)}</strong><span>${fmt(end)}</span></div>${milestones.length?`<div class="rock-milestone-list">${milestones.slice(0,4).map(i=>`<button data-edit="${i.id}"><span>${complete(i)?'✓':'◇'} ${fmt(i.due_at)}</span>${esc(i.title)}</button>`).join('')}</div>`:'<p class="muted micro">Add checkpoints to see the steps toward your outcome.</p>'}</section>`}
function workspaceSearch(){modal(`<p class="eyebrow">EVERYTHING CONNECTS</p><h2>Find your next thought.</h2><label>Search your workspace<input id="workspace-query" autofocus placeholder="Worlds, Projects, Rocks, notes…"></label><div id="workspace-results" class="workspace-results"></div>`);const results=q=>{q=q.trim().toLowerCase();$('#workspace-results').innerHTML=q?[...state.worlds.map(w=>({...w,type:'world',title:w.name})),...state.projects.map(p=>({...p,type:'project',title:p.name})),...state.items].filter(i=>(i.title+' '+(i.description||'')+' '+(i.summary||'')).toLowerCase().includes(q)).slice(0,20).map(i=>`<button ${i.type==='world'?'data-world':i.type==='project'?'data-project':i.type==='rock'?'data-rock':'data-edit'}="${i.id}"><span>${esc(i.title)}</span><small>${esc(i.type)}${i.archived_at?' · archived':''}</small></button>`).join('')||'<p class="muted">No matching records.</p>':'<p class="muted">Search titles and saved context across your Worlds.</p>'};$('#workspace-query').oninput=e=>results(e.target.value);results('');}

/** Round 3: Rock check-in when a linked Project reaches its date. */
function rockProjectCheck(id){const r=state.items.find(i=>i.id===id);if(!r||$('#modal').open)return;const t=today();const due=state.projects.filter(p=>p.rock===r.id&&!p.archived_at&&p.status!=='completed'&&p.due_at&&p.due_at<=t&&p.checked_on!==t);if(!due.length)return;const p=due[0];modal(`<p class="eyebrow">ROCK CHECK-IN · ${esc(r.title).toUpperCase()}</p><h2>Is “${esc(p.name)}” complete?</h2><p class="muted">This Project was due ${fmt(p.due_at)}. Projects are how a Rock gets done, so its status decides whether the Rock is on or off track.</p><div class="quick-actions check-in"><button class="primary" id="ci-complete">Yes, mark complete</button><button class="subtle-button" id="ci-on">Still moving · Rock on track</button><button class="subtle-button danger" id="ci-off">Behind · Rock off track</button></div>`);
  const finish=async(fn)=>{p.checked_on=t;fn();log('Rock check-in',r.id,p.name);if(await save()){$('#modal').close();render();rockProjectCheck(id)}};
  $('#ci-complete').onclick=()=>finish(()=>{p.status='completed';p.completed_at=stamp()});$('#ci-on').onclick=()=>finish(()=>{r.status='on'});$('#ci-off').onclick=()=>finish(()=>{r.status='off'});}
/** Round 3: CSV import from the template. */
async function importCsv(file){if(!file)return;const text=await file.text();const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const c=text[i];if(q){if(c==='"'&&text[i+1]==='"'){cell+='"';i++}else if(c==='"')q=false;else cell+=c}else if(c==='"')q=true;else if(c===','){row.push(cell);cell=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);rows.push(row);row=[];cell=''}else cell+=c}if(cell||row.length){row.push(cell);rows.push(row)}
  const head=rows.shift().map(h=>h.trim().toLowerCase());const col=n=>head.findIndex(h=>h.startsWith(n));const ix={type:col('type'),world:col('world'),title:col('title'),desc:col('desc'),due:col('due'),project:col('project'),rock:col('rock'),status:col('status')};if(ix.type<0||ix.title<0)return toast('The file needs at least Type and Title columns. Use the template.');
  const get=(r,k)=>(ix[k]>=0?r[ix[k]]||'':'').trim();const report=[];let made=0;const findWorld=n=>state.worlds.find(w=>!w.archived_at&&w.name.toLowerCase()===n.toLowerCase());
  const seq=[...rows.filter(r=>/^world/i.test(get(r,'type'))),...rows.filter(r=>/^rock/i.test(get(r,'type'))),...rows.filter(r=>/^project/i.test(get(r,'type'))),...rows.filter(r=>!/^(world|rock|project)/i.test(get(r,'type')))];
  for(const r of seq){const type=get(r,'type').toLowerCase(),title=get(r,'title');if(!title)continue;const due=get(r,'due');if(due&&!/^\d{4}-\d{2}-\d{2}$/.test(due)){report.push(`Skipped “${title}”: date must be YYYY-MM-DD.`);continue}
    if(type.startsWith('world')){if(findWorld(title)){report.push(`World “${title}” already exists.`);continue}if(state.worlds.filter(w=>!w.archived_at).length>=10){report.push(`Skipped World “${title}”: ten active Worlds is the limit.`);continue}state.worlds.push({id:uid(),name:title,headline:'',summary:get(r,'desc'),icon:'orb',color:WORLD_COLORS[state.worlds.length%WORLD_COLORS.length],created_at:stamp(),status_override:null});made++;continue}
    const w=findWorld(get(r,'world'))||state.worlds.find(x=>!x.archived_at);if(!w){report.push(`Skipped “${title}”: no World found.`);continue}
    const rock=get(r,'rock')?state.items.find(i=>i.type==='rock'&&i.world===w.id&&i.title.toLowerCase()===get(r,'rock').toLowerCase()):null;
    if(type.startsWith('project')){state.projects.push({id:uid(),name:title,headline:'',summary:get(r,'desc'),world:w.id,rock:rock?.id||'',due_at:due,status:/complete/i.test(get(r,'status'))?'completed':'open',tags:'',created_at:stamp()});made++;continue}
    const proj=get(r,'project')?state.projects.find(p=>p.world===w.id&&p.name.toLowerCase()===get(r,'project').toLowerCase()):null;
    const kind=type.startsWith('rock')?'rock':type.startsWith('issue')?'issue':type.startsWith('note')?'note':'todo';
    if(kind==='rock'&&!due){report.push(`Skipped Rock “${title}”: Rocks need a due date.`);continue}
    if(kind==='todo'&&due&&due>datePlus(today(),14)){report.push(`Skipped To-Do “${title}”: To-Dos may only be dated up to 14 days out. Make it a Project.`);continue}
    state.items.push({id:uid(),type:kind,title,description:get(r,'desc'),world:w.id,project:proj?.id||'',rock:rock?.id||'',due_at:due,status:kind==='rock'?(/off/i.test(get(r,'status'))?'off':'on'):'',created_at:stamp()});made++}
  state=normalize(state);log('Imported records from CSV',String(made));if(await save()){toast(made+' records imported.');render();const el=$('#import-report');if(el)el.innerHTML=`<strong>${made} record${made===1?'':'s'} imported.</strong>${report.map(l=>'<br>'+esc(l)).join('')}`}}
